import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { PixelIcon, type PixelIconInput } from "./pixel-icon";

const button = cva(
  "bk-cut bk-bricks inline-flex items-center justify-center font-pixel text-ink " +
    "cursor-pointer select-none rounded-none border-0 leading-none " +
    "shadow-[inset_calc(var(--px)*-1)_calc(var(--px)*-1)_0_var(--color-shade)] " +
    "min-h-[calc(var(--px)*8)] px-[calc(var(--px)*7)] gap-[calc(var(--px)*2)] " +
    "hover:not-disabled:bg-brick-hover " +
    "active:not-disabled:translate-y-[var(--px)] active:not-disabled:shadow-[inset_var(--px)_var(--px)_0_var(--color-shade)] " +
    "focus-visible:outline-none focus-visible:shadow-[inset_0_0_0_var(--px)_var(--color-ink)] " +
    "disabled:cursor-not-allowed disabled:bg-none disabled:bg-[#b98a5e] disabled:text-[#4a3522] " +
    "disabled:shadow-[inset_calc(var(--px)*-1)_calc(var(--px)*-1)_0_#8a6540]",
  {
    variants: {
      size: {
        sm: "[--px:4px] [--cut:1.5px] [--brick:2px] [--icon:3px] text-[11px]",
        md: "[--px:6px] [--cut:2px] [--brick:3px] [--icon:4px] text-[14px]",
        lg: "[--px:8px] [--cut:3px] [--brick:4px] [--icon:5px] text-[18px]"
      }
    },
    defaultVariants: { size: "md" }
  }
);

export interface BrickedButtonProps
  extends React.ComponentProps<"button">,
    VariantProps<typeof button> {
  icon?: PixelIconInput;
  iconPosition?: "left" | "right";
}

export function BrickedButton({
  className,
  size,
  icon,
  iconPosition = "left",
  children,
  ...props
}: BrickedButtonProps) {
  return (
    <button className={cn(button({ size }), className)} {...props}>
      {icon && iconPosition === "left" && <PixelIcon icon={icon} />}
      <span>{children}</span>
      {icon && iconPosition === "right" && <PixelIcon icon={icon} />}
    </button>
  );
}

/** Icon button - 48px square brick icon button with notification dot. */
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { PixelIcon, type PixelIconInput } from "./pixel-icon";

const iconButtonStyles = cva("bk-cut bk-bricks inline-flex items-center justify-center font-pixel text-ink cursor-pointer select-none rounded-none border-0 leading-none min-h-[calc(var(--px)*8)] px-[calc(var(--px)*7)] gap-[calc(var(--px)*2)]", {
  variants: {
    size: { sm: "[--px:4px] [--cut:1.5px] [--icon:3px] text-[11px]", md: "[--px:6px] [--cut:2px] [--icon:4px] text-[14px]", lg: "[--px:8px] [--cut:3px] [--icon:5px] text-[18px]" },
    variant: { primary: "bg-brick text-ink", dark: "bg-ink text-on-dark" },
  },
  defaultVariants: { size: "md", variant: "primary" },
});

export interface IconButtonProps extends React.ComponentProps<"button">, VariantProps<typeof iconButtonStyles> {
  icon?: PixelIconInput;
  iconPosition?: "left" | "right";
}

export function IconButton({ className, size, variant, icon, iconPosition = "left", children, ...props }: IconButtonProps) {
  return (
    <button className={cn(iconButtonStyles({ size, variant }), className)} {...props}>
      {icon && iconPosition === "left" && <PixelIcon icon={icon} />}
      {children ? <span>{children}</span> : null}
      {icon && iconPosition === "right" && <PixelIcon icon={icon} />}
    </button>
  );
}
